// Contract is the version of the contract the kinds keep: the JSON of a ticket, an event, the part of the organization and an answer, and what `start`, `next` and `worked` take and answer. A server refuses a package whose number it does not know.
const Contract = 3

// Lang is the language the sentences of the entries' errors are written in, `en` or `ja`: the language the package was written in (`ritsu gen --lang`). A refusal of the machine holds its sentence in both (`text` and `text_ja`).
const Lang = "en"

// Kind is a kind of request: its name and version, and its entries, which take the JSON of the contract and answer it.
type Kind struct {
	// Name is the request's name, in ASCII.
	Name string
	// Version is the request's version.
	Version int
	// Start is the entry for a request made: given the JSON of what is submitted and of the part of the organization, and the time in seconds, the answer as JSON (`ok` with the ticket and the things to do, or `err` with the refusal). A call that is no call of the contract is an error.
	Start func(submit json.RawMessage, organization json.RawMessage, now int64) (json.RawMessage, error)
	// Next is the entry for an event of a ticket: given the JSON of the ticket, the event and the part of the organization, and the time in seconds, the answer as JSON (`ok` with the ticket and the things to do, or `err` with the refusal). A call that is no call of the contract is an error.
	Next func(ticket json.RawMessage, event json.RawMessage, organization json.RawMessage, now int64) (json.RawMessage, error)
	// Worked is the entry for what the form works out: given the JSON of a form filled in so far and of what an approver gives or corrects in it (`{"form": …, "edited": … | null}`), the answer as JSON (`{"fields": …}`: whether each field shown or asked for on a condition is, and the value of each field the form works out, null where it is not decided). A call that is no call of the contract is an error.
	Worked func(in json.RawMessage) (json.RawMessage, error)
}

// workedAccount is the entry Worked of the kind account, whose form works nothing out: it reads what it is given as the contract's, and answers no field.
func workedAccount(in json.RawMessage) (json.RawMessage, error) {
	if _, err := readWorkedAccount(in); err != nil {
		return nil, err
	}
	return json.RawMessage(`{"fields":{}}`), nil
}

// workedAccountJa is the entry Worked of the kind account_ja, whose form works nothing out: it reads what it is given as the contract's, and answers no field.
func workedAccountJa(in json.RawMessage) (json.RawMessage, error) {
	if _, err := readWorkedAccountJa(in); err != nil {
		return nil, err
	}
	return json.RawMessage(`{"fields":{}}`), nil
}

